export function scriptClass(codePoint: number): number {
  let lo = 0;
  let hi = SCRIPT_TABLE.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const run = SCRIPT_TABLE[mid]!;
    if (codePoint < run[0]) hi = mid - 1;
    else if (codePoint > run[1]) lo = mid + 1;
    else return run[2];
  }
  return SCRIPT_OTHER;
}

