export function isCfOrMn(codePoint: number): boolean {
  let lo = 0;
  let hi = CF_MN.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const run = CF_MN[mid]!;
    if (codePoint < run[0]) hi = mid - 1;
    else if (codePoint > run[1]) lo = mid + 1;
    else return true;
  }
  return false;
}
